1	import type { Drawer, GridUnits, HeightUnits } from '@/core/types';
2	import { effectiveGridUnitMmY } from '@/core/types';
3	import { CONSTRAINTS, STAGING_ID } from '@/core/constants';
4	import { clamp } from '@/shared/utils/math';
5	import { drawerSizeFloors, isOutlineFullRectangle } from '@/shared/utils/drawerOutline';
6	import { computeDisplacedBins } from '@/core/cqrs/v2/domain/drawer/displacement';
7	import type { SetLocal } from './types';
8	
9	export function createDrawerActions(setLocal: SetLocal) {
10	  return {
11	    updateDrawer: (updates: Partial<Drawer>): void => {
12	      setLocal((state) => {
13	        const drawer = state.layout.drawer;
14	        const oldWidth = drawer.width as number;
15	        const oldDepth = drawer.depth as number;
16	        const gridUnitMmY = effectiveGridUnitMmY(state.layout);
17	
18	        // With a custom outline active the shrink floor rises to the
19	        // outline's bounding half-unit grid on any axis the recorded
20	        // measurement does not already hold — a resize must never mutate the
21	        // user's shape; same rule as the CQRS updateDrawer command.
22	        const floors = drawerSizeFloors(drawer, state.layout.gridUnitMm, gridUnitMmY);
23	
24	        if (updates.width !== undefined) {
25	          drawer.width = clamp(updates.width, floors.width, CONSTRAINTS.GRID_MAX) as GridUnits;
