import type { Page } from '@playwright/test';
import {
  test,
  expect,
  waitForAppReady,
  drawBinOnGrid,
  getGridBounds,
  waitForBinCount,
  waitForStashVisible,
  waitForStashHidden,
  waitForStagingBinCount,
  waitForBinSelected,
  clearAllStorage,
  resetViewport,
  getInspector,
  getStash,
  getActiveDialog,
  waitForAutoSave,
} from './fixtures';

/**
 * Helper to check stash bin count badge
 */
function getStashBinCount(page: Page) {
  // The bin count badge is a span with "N bins" text inside the stash header area
  // Note: i18n always uses "bins" regardless of count
  return getStash(page)
    .locator('span.text-xs')
    .filter({ hasText: /^\d+ bins$/ });
}

test.describe('Staging Area (Stash)', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await clearAllStorage(page);
    await page.reload();
    await waitForAppReady(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAllStorage(page);
    await resetViewport(page);

    // Close any lingering dialogs (excluding Labs drawer)
    const dialogs = getActiveDialog(page);
    if ((await dialogs.count()) > 0) {
      await page.keyboard.press('Escape');
      await dialogs.waitFor({ state: 'detached', timeout: 1000 }).catch(() => {});
    }
  });

  test('stash is hidden when empty', async ({ page }) => {
    // Stash container is always rendered, but should have no staging bins when empty
    await waitForStashHidden(page);
  });

