    await page.route('**/updateDrawer.ts*', async (route) => {
      const response = await route.fetch();
      const original = await response.text();
      const faulted = original.replace('if (event.payload.displacedBinIds.length > 0)', 'if (false)');
      if (faulted === original) throw new Error('V3 fault target not found in served module');
      await route.fulfill({ response, body: faulted, headers: { ...response.headers() } });
    });
    await page.goto('/');"""
out = src.replace("""  test.beforeEach(async ({ page }) => {
    await page.goto('/');""", fault, 1)
assert out != src
open('e2e/tmp-pilot-b-s2-v3-fault.spec.ts','w').write(out)
